syntax:
// Correct signature - returns reference
ClassName& operator=(const ClassName& other) {
  // ... assignment logic ...
  return *this;  // Dereference this pointer to get reference to current object
}

// Why it enables chaining:
a = b = c;
// Expands to:
a.operator=(b.operator=(c));
// Step 1: b.operator=(c) returns b&
// Step 2: a.operator=(b&) assigns from b

// Works with compound assignment too:
ClassName& operator+=(const ClassName& other) {
  // ... add other to this ...
  return *this;
}

a += b += c;  // Works because each += returns reference

// WRONG - breaks chaining:
void operator=(const ClassName& other) {  // void return
  // ...
  // a = b = c; won't compile
}

ClassName operator=(const ClassName& other) {  // returns by value
  // ...
  return *this;  // Unnecessary copy
  // a = b = c; works but inefficient
}

code_example:
#include <iostream>

class Counter {
    int value;

public:
    Counter(int v = 0) : value(v) {}

    Counter& operator=(const Counter& other) {
        std::cout << "Assigning " << other.value << " to " << value << "\n";
        value = other.value;
        return *this;  // Return reference to enable chaining
    }

    Counter& operator+=(int n) {
        value += n;
        return *this;  // Return reference for chaining
    }

    int get() const { return value; }
};

int main() {
    Counter a(10), b(20), c(30);

    std::cout << "=== Assignment chaining: a = b = c ===\n";
    a = b = c;

    std::cout << "\nResults:\n";
    std::cout << "a: " << a.get() << "\n";
    std::cout << "b: " << b.get() << "\n";
    std::cout << "c: " << c.get() << "\n";

    std::cout << "\n=== Compound assignment chaining: a += 5 ===\n";
    a += 5;
    std::cout << "a after += 5: " << a.get() << "\n";

    std::cout << "\n=== Multiple compound: (a += 10) += 20 ===\n";
    (a += 10) += 20;
    std::cout << "a after chained +=: " << a.get() << "\n";

    return 0;
}
